// 단일 파일 완전 자립형 스켈레톤 HTML 코드 (Tailwind CDN + Vanilla JS + Firebase CDN)
export const SKELETON_HTML_CODE = "<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>순환보직 관리 시스템 - 직원 경력 정보 및 배점 산출 SPA</title>\n  \n  <!-- 1. Tailwind CSS CDN 로드 -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <script>\n    tailwind.config = {\n      theme: {\n        extend: {\n          colors: {\n            brand: {\n              50: '#eef2ff',\n              100: '#e0e7ff',\n              200: '#c7d2fe',\n              500: '#6366f1',\n              600: '#4f46e5',\n              700: '#4338ca',\n              800: '#3730a3',\n            }\n          }\n        }\n      }\n    }\n  </script>\n\n  <!-- 웹 폰트 (Pretendard) 로드 -->\n  <link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/static/pretendard.min.css\" />\n  <style>\n    body {\n      font-family: 'Pretendard', -apple-system, BlinkMacSystemFont, system-ui, sans-serif;\n    }\n    .view-section {\n      display: none;\n    }\n    .view-section.active {\n      display: block;\n    }\n  </style>\n</head>\n<body class=\"bg-slate-50 text-slate-800 min-h-screen flex flex-col antialiased\">\n\n  <!-- [상단 헤더] -->\n  <header class=\"bg-white border-b border-slate-200 sticky top-0 z-40 shadow-xs\">\n    <div class=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between\">\n      \n      <div class=\"flex items-center space-x-3 cursor-pointer\" onclick=\"ViewController.navigate('login')\">\n        <div class=\"w-10 h-10 rounded-xl bg-gradient-to-tr from-brand-600 to-indigo-500 flex items-center justify-center text-white font-bold shadow-md shadow-brand-500/20\">\n          <svg class=\"w-6 h-6\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4M7.835 4.697a3.42 3.42 0 001.946-.806 3.42 3.42 0 014.438 0 3.42 3.42 0 001.946.806 3.42 3.42 0 013.138 3.138 3.42 3.42 0 00.806 1.946 3.42 3.42 0 010 4.438 3.42 3.42 0 00-.806 1.946 3.42 3.42 0 01-3.138 3.138 3.42 3.42 0 00-1.946.806 3.42 3.42 0 01-4.438 0 3.42 3.42 0 00-1.946-.806 3.42 3.42 0 01-3.138-3.138 3.42 3.42 0 00-.806-1.946 3.42 3.42 0 010-4.438 3.42 3.42 0 00.806-1.946 3.42 3.42 0 013.138-3.138z\" />\n          </svg>\n        </div>\n        <div>\n          <span class=\"text-lg font-bold text-slate-900 tracking-tight\">순환보직 평정 시스템</span>\n          <span class=\"hidden sm:inline-block ml-2 px-2 py-0.5 text-xs font-semibold bg-brand-50 text-brand-600 rounded-full border border-brand-200\">\n            경력 배점 평가\n          </span>\n        </div>\n      </div>\n\n      <nav id=\"nav-controls\" class=\"flex items-center space-x-1 sm:space-x-2\">\n        <button id=\"nav-btn-login\" onclick=\"ViewController.navigate('login')\" \n          class=\"px-3.5 py-1.5 rounded-lg text-sm font-medium text-slate-600 hover:text-brand-600 hover:bg-slate-100 transition-colors\">\n          로그인 / 가입\n        </button>\n        <button id=\"nav-btn-career\" onclick=\"ViewController.navigate('career')\" \n          class=\"px-3.5 py-1.5 rounded-lg text-sm font-medium text-slate-600 hover:text-brand-600 hover:bg-slate-100 transition-colors\">\n          경력 정보 및 배점 입력\n        </button>\n        <button id=\"nav-btn-admin\" onclick=\"ViewController.navigate('admin')\" \n          class=\"px-3.5 py-1.5 rounded-lg text-sm font-medium text-slate-600 hover:text-brand-600 hover:bg-slate-100 transition-colors\">\n          관리자 대시보드\n        </button>\n      </nav>\n\n      <div class=\"flex items-center space-x-3\">\n        <div id=\"user-badge\" class=\"hidden items-center space-x-2 bg-slate-100 px-3 py-1.5 rounded-full border border-slate-200\">\n          <span class=\"w-2.5 h-2.5 rounded-full bg-emerald-500\"></span>\n          <span id=\"user-name-display\" class=\"text-xs font-semibold text-slate-700\">홍길동 (2학년 3반)</span>\n          <button onclick=\"AuthService.handleSignOut()\" class=\"text-xs text-rose-500 hover:underline font-semibold ml-1\">\n            로그아웃\n          </button>\n        </div>\n      </div>\n    </div>\n  </header>\n\n  <!-- 알림 토스트 -->\n  <div id=\"toast-container\" class=\"fixed top-20 right-5 z-50 flex flex-col space-y-2 pointer-events-none\"></div>\n\n  <!-- [경고창 모달: 로그인을 해주세요] -->\n  <div id=\"warning-modal\" class=\"hidden fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-xs p-4\">\n    <div class=\"bg-white rounded-3xl max-w-sm w-full p-6 shadow-2xl border border-slate-200 text-center space-y-4\">\n      <div class=\"w-14 h-14 rounded-2xl bg-amber-100 text-amber-600 mx-auto flex items-center justify-center font-bold\">\n        <svg class=\"w-8 h-8\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z\"/></svg>\n      </div>\n      <div>\n        <h3 class=\"text-lg font-black text-slate-900\">알림</h3>\n        <p id=\"warning-modal-text\" class=\"text-sm font-bold text-amber-700 mt-2 bg-amber-50 py-2 px-3 rounded-xl border border-amber-200/60\">\n          로그인을 해주세요.\n        </p>\n        <p class=\"text-xs text-slate-500 mt-2\">\n          경력 정보 입력 및 관리자 기능은 로그인 완료 후 이용하실 수 있습니다.\n        </p>\n      </div>\n      <button onclick=\"closeWarningModal()\" class=\"w-full py-3 bg-brand-600 hover:bg-brand-700 active:bg-brand-800 text-white font-bold rounded-xl text-sm transition shadow-md shadow-brand-500/25 flex items-center justify-center space-x-1.5 cursor-pointer\">\n        <svg class=\"w-4 h-4 mr-1 text-white\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M10 19l-7-7m0 0l7-7m-7 7h18\"/></svg>\n        <span>뒤로가기</span>\n      </button>\n    </div>\n  </div>\n\n  <!-- [관리자 삭제 확인 모달: 평정 기록 및 로그인 계정 영구 삭제] -->\n  <div id=\"admin-delete-modal\" class=\"hidden fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-xs p-4\">\n    <div class=\"bg-white rounded-3xl max-w-md w-full p-6 shadow-2xl border border-slate-200 space-y-4\">\n      <div class=\"w-14 h-14 rounded-2xl bg-rose-100 text-rose-600 mx-auto flex items-center justify-center font-bold\">\n        <svg class=\"w-7 h-7\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z\"/></svg>\n      </div>\n\n      <div class=\"text-center space-y-2\">\n        <h3 class=\"text-lg font-black text-slate-900\">\n          평정 데이터 & 로그인 정보 영구 삭제\n        </h3>\n        <p class=\"text-xs text-slate-500\">\n          선택하신 교직원의 평정 기록과 로그인 계정 정보를 한꺼번에 삭제합니다.\n        </p>\n\n        <div class=\"p-4 bg-rose-50 border border-rose-200 rounded-2xl text-left space-y-2 text-xs text-rose-950 mt-3\">\n          <div class=\"flex justify-between items-center\">\n            <span class=\"font-semibold text-rose-700\">교직원 이름:</span>\n            <span id=\"delete-target-name\" class=\"font-bold text-slate-900 text-sm\">홍길동</span>\n          </div>\n          <div class=\"flex justify-between items-center\">\n            <span class=\"font-semibold text-rose-700\">소속(학년/반):</span>\n            <span id=\"delete-target-aff\" class=\"font-bold text-slate-800\">2학년 3반</span>\n          </div>\n          <div class=\"flex justify-between items-center\">\n            <span class=\"font-semibold text-rose-700\">총 배점 점수:</span>\n            <span id=\"delete-target-score\" class=\"font-black text-rose-600\">75점</span>\n          </div>\n          <div class=\"pt-2 border-t border-rose-200/80 text-[11px] text-rose-700 font-medium leading-relaxed\">\n            ⚠️ <strong>주의:</strong> 삭제 실행 시 Firestore의 <code class=\"bg-white px-1 py-0.5 rounded border border-rose-200 font-bold\">rotation_records</code> 평정 데이터뿐만 아니라 <code class=\"bg-white px-1 py-0.5 rounded border border-rose-200 font-bold\">users</code> 로그인 계정 정보까지 한꺼번에 완전 삭제되며 복구할 수 없습니다.\n          </div>\n        </div>\n      </div>\n\n      <div class=\"grid grid-cols-2 gap-3 pt-2\">\n        <button type=\"button\" onclick=\"CareerScoreApp.closeDeleteModal()\" class=\"w-full py-3 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-xl text-xs transition cursor-pointer\">\n          취소\n        </button>\n        <button type=\"button\" onclick=\"CareerScoreApp.executeDelete()\" class=\"w-full py-3 bg-rose-600 hover:bg-rose-700 text-white font-black rounded-xl text-xs transition shadow-md shadow-rose-500/25 flex items-center justify-center space-x-1.5 cursor-pointer\">\n          <svg class=\"w-4 h-4 mr-1\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16\" /></svg>\n          <span>영구 삭제 실행</span>\n        </button>\n      </div>\n    </div>\n  </div>\n\n  <!-- [MODAL: 관리자 비밀번호 변경] -->\n  <div id=\"admin-pw-modal\" class=\"hidden fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-xs p-4\">\n    <div class=\"bg-white rounded-3xl max-w-md w-full p-6 sm:p-7 shadow-2xl border border-slate-200 space-y-4\">\n      <div class=\"flex justify-between items-start\">\n        <div class=\"w-12 h-12 rounded-2xl bg-purple-100 text-purple-600 flex items-center justify-center shadow-inner\">\n          <svg class=\"w-6 h-6\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M15 7a2 2 0 012 2m4 0a6 6 0 01-7.743 5.743L11 17H9v2H7v2H4a1 1 0 01-1-1v-2.586a1 1 0 01.293-.707l5.964-5.964A6 6 0 1121 9z\" /></svg>\n        </div>\n        <button type=\"button\" onclick=\"CareerScoreApp.closePasswordModal()\" class=\"text-slate-400 hover:text-slate-600 p-1.5 rounded-xl hover:bg-slate-100 transition cursor-pointer\">\n          <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\" /></svg>\n        </button>\n      </div>\n\n      <div>\n        <h3 class=\"text-lg font-black text-slate-900\">관리자 비밀번호 변경</h3>\n        <p class=\"text-xs text-slate-500 mt-1 leading-relaxed\">\n          현재 관리자 비밀번호를 확인한 후, 새로운 비밀번호를 2번 반복하여 입력해 주세요.\n        </p>\n      </div>\n\n      <div id=\"pw-error-box\" class=\"hidden p-3 bg-rose-50 border border-rose-200 rounded-xl text-xs font-semibold text-rose-700 flex items-center space-x-2\">\n        <span id=\"pw-error-msg\"></span>\n      </div>\n      <div id=\"pw-success-box\" class=\"hidden p-3 bg-emerald-50 border border-emerald-200 rounded-xl text-xs font-semibold text-emerald-700 flex items-center space-x-2\">\n        <span id=\"pw-success-msg\"></span>\n      </div>\n\n      <form onsubmit=\"CareerScoreApp.submitChangePassword(event)\" class=\"space-y-3.5 pt-1\">\n        <div>\n          <label class=\"block text-xs font-bold text-slate-700 mb-1\">\n            이전 비밀번호 <span class=\"text-rose-500\">*</span>\n          </label>\n          <input type=\"password\" id=\"pw-current\" required placeholder=\"현재 관리자 비밀번호를 입력하세요\"\n            class=\"w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium focus:ring-2 focus:ring-purple-500 focus:outline-hidden transition\" />\n        </div>\n\n        <div>\n          <label class=\"block text-xs font-bold text-slate-700 mb-1\">\n            새로운 비밀번호 <span class=\"text-rose-500\">*</span>\n          </label>\n          <input type=\"password\" id=\"pw-new\" required placeholder=\"새로운 비밀번호를 입력하세요 (4자 이상)\"\n            class=\"w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium focus:ring-2 focus:ring-purple-500 focus:outline-hidden transition\" />\n        </div>\n\n        <div>\n          <label class=\"block text-xs font-bold text-slate-700 mb-1\">\n            새로운 비밀번호 확인 <span class=\"text-rose-500\">*</span>\n          </label>\n          <input type=\"password\" id=\"pw-new-confirm\" required placeholder=\"새로운 비밀번호를 한 번 더 입력하세요\"\n            class=\"w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium focus:ring-2 focus:ring-purple-500 focus:outline-hidden transition\" />\n        </div>\n\n        <div class=\"grid grid-cols-2 gap-3 pt-3\">\n          <button type=\"button\" onclick=\"CareerScoreApp.closePasswordModal()\"\n            class=\"w-full py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-xl text-xs transition cursor-pointer\">\n            취소\n          </button>\n          <button type=\"submit\"\n            class=\"w-full py-2.5 bg-purple-600 hover:bg-purple-700 active:bg-purple-800 text-white font-black rounded-xl text-xs transition shadow-md shadow-purple-500/25 flex items-center justify-center space-x-1.5 cursor-pointer\">\n            <svg class=\"w-3.5 h-3.5 mr-1\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M15 7a2 2 0 012 2m4 0a6 6 0 01-7.743 5.743L11 17H9v2H7v2H4a1 1 0 01-1-1v-2.586a1 1 0 01.293-.707l5.964-5.964A6 6 0 1121 9z\" /></svg>\n            <span>변경하기</span>\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <main class=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 flex-1 w-full\">\n\n    <!-- [VIEW 1] 로그인 / 회원가입 화면 -->\n    <section id=\"view-login\" class=\"view-section active\">\n      <div class=\"max-w-md mx-auto bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden\">\n        \n        <div class=\"bg-gradient-to-r from-brand-600 to-indigo-600 p-6 text-white text-center\">\n          <div class=\"w-14 h-14 bg-white/20 backdrop-blur-xs rounded-2xl mx-auto flex items-center justify-center mb-3\">\n            <svg class=\"w-8 h-8 text-white\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n              <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z\" />\n            </svg>\n          </div>\n          <h2 class=\"text-2xl font-bold\" id=\"auth-title\">순환보직 평정 시스템 로그인</h2>\n          <p class=\"text-brand-100 text-xs mt-1\" id=\"auth-subtitle\">이름과 학년/반(소속)으로 로그인하세요.</p>\n        </div>\n\n        <!-- 탭 전환 -->\n        <div class=\"grid grid-cols-2 p-1.5 bg-slate-100 border-b border-slate-200\">\n          <button id=\"tab-login\" onclick=\"AuthService.switchAuthMode('login')\" \n            class=\"py-2 text-xs font-bold rounded-lg transition-all bg-white text-brand-600 shadow-xs\">\n            로그인\n          </button>\n          <button id=\"tab-signup\" onclick=\"AuthService.switchAuthMode('signup')\" \n            class=\"py-2 text-xs font-bold rounded-lg transition-all text-slate-500 hover:text-slate-800\">\n            신규 회원가입\n          </button>\n        </div>\n\n        <form id=\"form-auth\" onsubmit=\"AuthService.handleSubmit(event)\" class=\"p-6 space-y-4\">\n          <!-- 1. 이름 -->\n          <div>\n            <label for=\"auth-name\" class=\"block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1\">\n              이름 <span class=\"text-rose-500\">*</span>\n            </label>\n            <input type=\"text\" id=\"auth-name\" oninput=\"AuthService.updateLoginButtonState()\" placeholder=\"이름을 입력하세요 (예: 홍길동)\" \n              class=\"w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:outline-hidden focus:ring-2 focus:ring-brand-500 text-sm transition\" />\n          </div>\n\n          <!-- 2. 학년/반(소속) -->\n          <div>\n            <label for=\"auth-affiliation\" class=\"block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1\">\n              학년 / 반 (소속) <span class=\"text-rose-500\">*</span>\n            </label>\n            <input type=\"text\" id=\"auth-affiliation\" oninput=\"AuthService.updateLoginButtonState()\" placeholder=\"소속을 입력하세요 (예: 교무부 / admin은 비워둘 시 자동 적용)\" \n              class=\"w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:outline-hidden focus:ring-2 focus:ring-brand-500 text-sm transition\" />\n          </div>\n\n          <!-- 3. 비밀번호 -->\n          <div>\n            <label for=\"auth-password\" class=\"block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1\">\n              비밀번호 <span class=\"text-rose-500\">*</span>\n            </label>\n            <input type=\"password\" id=\"auth-password\" oninput=\"AuthService.updateLoginButtonState()\" placeholder=\"비밀번호를 입력하세요\" \n              class=\"w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:outline-hidden focus:ring-2 focus:ring-brand-500 text-sm transition\" />\n          </div>\n\n          <!-- 회원가입 전용 비밀번호 확인 -->\n          <div id=\"field-password-confirm\" class=\"hidden\">\n            <label for=\"auth-password-confirm\" class=\"block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1\">\n              비밀번호 확인 <span class=\"text-rose-500\">*</span>\n            </label>\n            <input type=\"password\" id=\"auth-password-confirm\" oninput=\"AuthService.updateLoginButtonState()\" placeholder=\"비밀번호를 한 번 더 입력하세요\" \n              class=\"w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:outline-hidden focus:ring-2 focus:ring-brand-500 text-sm transition\" />\n          </div>\n\n          <!-- 관리자 체크박스 -->\n          <div class=\"py-0.5\">\n            <label class=\"relative flex items-center p-2.5 rounded-xl border border-slate-200/80 bg-slate-50 hover:bg-slate-100 cursor-pointer select-none transition\">\n              <input type=\"checkbox\" id=\"auth-is-admin\" class=\"w-4 h-4 text-brand-600 rounded-sm border-slate-300 focus:ring-brand-500 cursor-pointer\" />\n              <div class=\"ml-2.5\">\n                <span class=\"text-xs font-bold text-slate-800 block\" id=\"admin-chk-label\">관리자(교사 / 인사담당자)로 로그인</span>\n                <span class=\"text-[10px] text-slate-400 block\">아이디: admin, 비밀번호: 112233 (초기값) 입력 시 관리자 대시보드로 이동</span>\n              </div>\n            </label>\n          </div>\n\n          <!-- =========================================================================\n               [비밀번호 입력창 바로 아래 직관적인 로그인 및 가입 버튼 배치]\n               - 이름, 학년/반, 비밀번호가 모두 입력되면 '로그인' 텍스트가 진하게 표시됨\n          ========================================================================= -->\n          <div id=\"btn-login-single\" class=\"pt-1\">\n            <button type=\"submit\" id=\"btn-login-submit\"\n              class=\"w-full py-3.5 bg-slate-200 hover:bg-slate-300 text-slate-700 font-bold border border-slate-300 rounded-xl transition flex items-center justify-center space-x-2 text-sm cursor-pointer\">\n              <span id=\"login-text\" class=\"font-bold text-slate-700 text-sm\">로그인</span>\n              <svg class=\"w-4 h-4 ml-0.5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M14 5l7 7m0 0l-7 7m7-7H3\"/></svg>\n            </button>\n            <p id=\"login-guide-hint\" class=\"text-[11px] text-center text-slate-500 mt-1.5 font-medium\">\n              ※ 이름, 학년/반(소속), 비밀번호를 모두 입력하면 로그인 버튼이 활성화됩니다.\n            </p>\n          </div>\n\n          <!-- 회원가입 모드 버튼 그룹 -->\n          <div id=\"btn-signup-group\" class=\"hidden grid grid-cols-2 gap-3 pt-1\">\n            <button type=\"button\" onclick=\"AuthService.switchAuthMode('login')\"\n              class=\"w-full py-3 bg-slate-100 hover:bg-slate-200 text-slate-700 font-semibold rounded-xl transition flex items-center justify-center text-sm cursor-pointer\">\n              취소\n            </button>\n            <button type=\"submit\" id=\"btn-signup-submit\"\n              class=\"w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-xl transition shadow-md shadow-indigo-500/25 flex items-center justify-center space-x-1.5 text-sm cursor-pointer select-none\">\n              <span id=\"signup-text\" class=\"text-white font-black text-sm\">가입하기</span>\n              <svg id=\"signup-arrow\" class=\"w-4 h-4 text-white ml-0.5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M14 5l7 7m0 0l-7 7m7-7H3\"/></svg>\n            </button>\n          </div>\n\n        </form>\n\n      </div>\n    </section>\n\n    <!-- [VIEW 2] 직원 경력 정보 입력 및 배점 계산 페이지 -->\n    <section id=\"view-career\" class=\"view-section\">\n      <div class=\"max-w-4xl mx-auto space-y-8\">\n        \n        <div class=\"bg-white rounded-2xl p-6 border border-slate-200 shadow-xs flex flex-col md:flex-row md:items-center justify-between gap-4\">\n          <div>\n            <div class=\"flex items-center space-x-2\">\n              <span class=\"px-2.5 py-0.5 text-xs font-bold rounded-full bg-brand-50 text-brand-700 border border-brand-200\">\n                100점 만점 평정 기준\n              </span>\n              <span class=\"text-xs text-slate-400\">엑셀 시트 연동 가능</span>\n            </div>\n            <h2 class=\"text-xl font-bold text-slate-900 mt-1\">직원 경력 정보 입력 및 순환 배점 산출</h2>\n            <p class=\"text-xs text-slate-500 mt-1\">\n              나이, 재직기간, 총경력을 입력하면 실시간 배점이 계산되며, 저장 시 평정 데이터베이스에 등록됩니다.\n            </p>\n          </div>\n        </div>\n\n        <div class=\"bg-white rounded-2xl shadow-xs border border-slate-200 overflow-hidden\">\n          <div class=\"p-6 border-b border-slate-100 bg-slate-50/50\">\n            <h3 class=\"font-bold text-slate-900 text-base flex items-center\">\n              <span class=\"w-2.5 h-2.5 rounded-full bg-brand-600 mr-2\"></span>\n              경력 세부 사항 작성\n            </h3>\n            <p class=\"text-xs text-slate-500 mt-0.5\">수치를 입력하면 즉시 실시간 배점이 산출됩니다.</p>\n          </div>\n\n          <form id=\"form-career-score\" onsubmit=\"CareerScoreApp.handleSaveRecord(event)\" class=\"p-6 space-y-6\">\n            <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n              <div>\n                <label for=\"career-name\" class=\"block text-xs font-bold text-slate-700 mb-1\">\n                  이름 <span class=\"text-rose-500\">*</span>\n                </label>\n                <input type=\"text\" id=\"career-name\" required placeholder=\"홍길동\" \n                  class=\"w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-brand-500\" />\n              </div>\n\n              <div>\n                <label for=\"career-age\" class=\"block text-xs font-bold text-slate-700 mb-1\">\n                  나이 (만 세) <span class=\"text-rose-500\">*</span>\n                </label>\n                <div class=\"relative\">\n                  <input type=\"text\" inputmode=\"numeric\" id=\"career-age\" required value=\"52\" placeholder=\"예: 52\"\n                    oninput=\"CareerScoreApp.handleLiveCalc()\"\n                    class=\"w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-brand-500 font-semibold\" />\n                  <span class=\"absolute right-3.5 top-2.5 text-xs text-slate-400\">세</span>\n                </div>\n                <div class=\"flex justify-between text-[11px] text-slate-400 mt-1\">\n                  <span>55세↑(30점)</span>\n                  <span>50~54세(25점)</span>\n                  <span>45~49세(20점)</span>\n                  <span>40~44세(15점)</span>\n                  <span>40세↓(10점)</span>\n                </div>\n              </div>\n\n              <div>\n                <label for=\"career-tenure\" class=\"block text-xs font-bold text-slate-700 mb-1\">\n                  본교/당사 재직기간 (년) <span class=\"text-rose-500\">*</span>\n                </label>\n                <div class=\"relative\">\n                  <input type=\"text\" inputmode=\"decimal\" id=\"career-tenure\" required value=\"8.00\" placeholder=\"예: 1.06 (1년 6개월)\"\n                    oninput=\"CareerScoreApp.handleLiveCalc()\"\n                    class=\"w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-brand-500 font-semibold\" />\n                  <span class=\"absolute right-3.5 top-2.5 text-xs text-slate-400\">년</span>\n                </div>\n\n                <!-- [요구사항 핵심] 입력 예시 가이드 및 실시간 환산 -->\n                <div class=\"mt-1.5 bg-indigo-50/80 border border-indigo-100 rounded-lg p-2 text-xs space-y-1\">\n                  <div class=\"text-indigo-900 font-semibold text-[11px] leading-relaxed\">\n                    💡 <strong>입력예시:</strong> 1년 6개월은 <code class=\"bg-white px-1 py-0.5 rounded text-indigo-700 font-bold border border-indigo-200\">1.06</code>, 2년 2개월은 <code className=\"bg-white px-1 py-0.5 rounded text-indigo-700 font-bold border border-indigo-200\">2.02</code>, 2년 11개월은 <code class=\"bg-white px-1 py-0.5 rounded text-indigo-700 font-bold border border-indigo-200\">2.11</code>로 직접 입력하세요.\n                  </div>\n                  <div class=\"text-[11px] text-indigo-700 flex items-center pt-0.5\">\n                    <span class=\"font-bold mr-1.5\">실시간 환산:</span>\n                    <span id=\"career-tenure-convert\" class=\"bg-white px-2 py-0.5 rounded border border-indigo-200 font-black text-indigo-800\">8년</span>\n                  </div>\n                </div>\n\n                <div class=\"flex justify-between text-[11px] text-slate-400 mt-1\">\n                  <span>10년↑ (30점)</span>\n                  <span>5~9년 (20점)</span>\n                  <span>1~4년 (10점)</span>\n                  <span>1년미만 (0점)</span>\n                </div>\n              </div>\n\n              <div>\n                <label for=\"career-total-exp\" class=\"block text-xs font-bold text-slate-700 mb-1\">\n                  총 경력 기간 (년) <span class=\"text-rose-500\">*</span>\n                </label>\n                <div class=\"relative\">\n                  <input type=\"text\" inputmode=\"decimal\" id=\"career-total-exp\" required value=\"16.00\" placeholder=\"예: 2.11 (2년 11개월)\"\n                    oninput=\"CareerScoreApp.handleLiveCalc()\"\n                    class=\"w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-brand-500 font-semibold\" />\n                  <span class=\"absolute right-3.5 top-2.5 text-xs text-slate-400\">년</span>\n                </div>\n\n                <!-- [요구사항 핵심] 입력 예시 가이드 및 실시간 환산 -->\n                <div class=\"mt-1.5 bg-purple-50/80 border border-purple-100 rounded-lg p-2 text-xs space-y-1\">\n                  <div class=\"text-purple-900 font-semibold text-[11px] leading-relaxed\">\n                    💡 <strong>입력예시:</strong> 1년 6개월은 <code class=\"bg-white px-1 py-0.5 rounded text-purple-700 font-bold border border-purple-200\">1.06</code>, 2년 2개월은 <code class=\"bg-white px-1 py-0.5 rounded text-purple-700 font-bold border border-purple-200\">2.02</code>, 2년 11개월은 <code class=\"bg-white px-1 py-0.5 rounded text-purple-700 font-bold border border-purple-200\">2.11</code>로 직접 입력하세요.\n                  </div>\n                  <div class=\"text-[11px] text-purple-700 flex items-center pt-0.5\">\n                    <span class=\"font-bold mr-1.5\">실시간 환산:</span>\n                    <span id=\"career-exp-convert\" class=\"bg-white px-2 py-0.5 rounded border border-purple-200 font-black text-purple-800\">16년</span>\n                  </div>\n                </div>\n\n                <div class=\"flex justify-between text-[11px] text-slate-400 mt-1\">\n                  <span>20년↑ (40점)</span>\n                  <span>10~19년 (30점)</span>\n                  <span>5~9년 (20점)</span>\n                  <span>5년↓ (10점)</span>\n                </div>\n              </div>\n            </div>\n\n            <div>\n              <label for=\"career-duties\" class=\"block text-xs font-bold text-slate-700 mb-1\">\n                올해 나의 업무 (담당 직무 및 주요 과업) <span class=\"text-rose-500\">*</span>\n              </label>\n              <textarea id=\"career-duties\" rows=\"3\" required placeholder=\"올해 담당하고 있는 주요 업무, 수업, 담당 프로젝트 등을 구체적으로 서술하세요.\" \n                class=\"w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-brand-500\">영업기획팀 파이프라인 관리 및 2학년 취업 진로 상담 전담, 사내 데이터 대시보드 프로젝트 주도</textarea>\n            </div>\n\n            <div class=\"grid grid-cols-3 gap-3 text-center bg-slate-50 p-4 rounded-xl border border-slate-200\">\n              <div class=\"bg-white p-3 rounded-lg border border-slate-100\">\n                <span class=\"text-xs text-slate-500 block\">나이 배점 (30점 만점)</span>\n                <span class=\"text-lg font-bold text-brand-600\" id=\"live-age-score\">25점</span>\n              </div>\n              <div class=\"bg-white p-3 rounded-lg border border-slate-100\">\n                <span class=\"text-xs text-slate-500 block\">재직기간 배점 (30점 만점)</span>\n                <span class=\"text-lg font-bold text-indigo-600\" id=\"live-tenure-score\">20점</span>\n              </div>\n              <div class=\"bg-white p-3 rounded-lg border border-slate-100\">\n                <span class=\"text-xs text-slate-500 block\">총경력 배점 (40점 만점)</span>\n                <span class=\"text-lg font-bold text-purple-600\" id=\"live-exp-score\">30점</span>\n              </div>\n            </div>\n\n            <div class=\"flex justify-end space-x-3\">\n              <button type=\"submit\" class=\"px-6 py-2.5 bg-brand-600 hover:bg-brand-700 text-white rounded-xl text-sm font-semibold shadow-md\">\n                저장하기 (Firestore rotation_records)\n              </button>\n            </div>\n          </form>\n        </div>\n\n        <div id=\"result-score-container\" class=\"bg-gradient-to-r from-brand-600 to-indigo-600 rounded-2xl p-6 text-white shadow-xl flex items-center justify-between\">\n          <div>\n            <span class=\"px-2.5 py-0.5 rounded-full bg-white/20 text-xs font-semibold\">Firestore 저장 완료</span>\n            <h3 class=\"text-2xl font-bold mt-1\"><span id=\"result-user-name\">홍길동</span> 님의 순환보직 평정 결과</h3>\n            <p class=\"text-xs text-brand-100 mt-1\" id=\"result-timestamp\">평정 일시: 2026-10-28 19:40</p>\n          </div>\n          <div class=\"bg-white/15 backdrop-blur-md rounded-2xl p-4 border border-white/20 text-center min-w-[180px]\">\n            <span class=\"text-xs text-brand-100\">나의 총 배점점수</span>\n            <div class=\"text-5xl font-black mt-1\" id=\"result-total-score\">75</div>\n            <span class=\"text-xs text-brand-200\">/ 100점 만점</span>\n          </div>\n        </div>\n\n      </div>\n    </section>\n\n    <!-- [VIEW 3] 관리자 대시보드 -->\n    <section id=\"view-admin\" class=\"view-section\">\n      <div class=\"bg-white rounded-2xl shadow-xs border border-slate-200 overflow-hidden\">\n        <div class=\"p-5 border-b border-slate-200 flex flex-col sm:flex-row sm:items-center justify-between gap-4\">\n          <div>\n            <h3 class=\"text-lg font-bold text-slate-900\">직원 경력 정보 및 순환 배점 집계표 (rotation_records)</h3>\n            <p class=\"text-xs text-slate-500\">배점 기준 내림차순 정렬</p>\n          </div>\n          <div class=\"flex items-center gap-2\">\n            <button type=\"button\" onclick=\"CareerScoreApp.openPasswordModal()\"\n              class=\"px-3.5 py-2 bg-purple-50 hover:bg-purple-100 text-purple-700 border border-purple-200 rounded-xl text-xs font-bold transition flex items-center space-x-1.5 shadow-xs cursor-pointer\">\n              <svg class=\"w-3.5 h-3.5 text-purple-600\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M15 7a2 2 0 012 2m4 0a6 6 0 01-7.743 5.743L11 17H9v2H7v2H4a1 1 0 01-1-1v-2.586a1 1 0 01.293-.707l5.964-5.964A6 6 0 1121 9z\" /></svg>\n              <span>관리자 비밀번호 변경</span>\n            </button>\n            <button id=\"btn-admin-delete\" onclick=\"CareerScoreApp.handleDeleteSelected()\" disabled\n              class=\"px-3.5 py-2 rounded-xl text-xs font-bold transition flex items-center space-x-1.5 bg-slate-100 text-slate-400 border border-slate-200 cursor-not-allowed opacity-60\">\n              <svg class=\"w-3.5 h-3.5 text-rose-500\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16\" /></svg>\n              <span>선택 삭제 (로그인 계정 포함)</span>\n            </button>\n          </div>\n        </div>\n        <div class=\"overflow-x-auto\">\n          <table class=\"w-full text-left text-sm\">\n            <thead class=\"bg-slate-50 text-slate-500 text-xs uppercase border-b border-slate-200\">\n              <tr>\n                <th class=\"px-3.5 py-3 text-center w-12\">선택</th>\n                <th class=\"px-5 py-3\">순위</th>\n                <th class=\"px-5 py-3\">이름 / 소속</th>\n                <th class=\"px-5 py-3\">경력 스펙</th>\n                <th class=\"px-5 py-3\">배점 내역</th>\n                <th class=\"px-5 py-3 text-center\">총 배점점수</th>\n                <th class=\"px-5 py-3\">올해 업무</th>\n                <th class=\"px-5 py-3 text-right\">관리 작업</th>\n              </tr>\n            </thead>\n            <tbody id=\"admin-records-table-body\" class=\"divide-y divide-slate-100\">\n              <!-- JS 렌더링 -->\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </section>\n\n  </main>\n\n  <script type=\"module\">\n    import { initializeApp } from \"https://www.gstatic.com/firebasejs/10.8.0/firebase-app.js\";\n    import { getAuth, signInWithEmailAndPassword, signOut } from \"https://www.gstatic.com/firebasejs/10.8.0/firebase-auth.js\";\n    import { getFirestore, collection, addDoc, getDocs, doc, serverTimestamp } from \"https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js\";\n\n    const firebaseConfig = {\n      apiKey: \"YOUR_API_KEY\",\n      authDomain: \"YOUR_PROJECT_ID.firebaseapp.com\",\n      projectId: \"YOUR_PROJECT_ID\",\n      storageBucket: \"YOUR_PROJECT_ID.appspot.com\",\n      messagingSenderId: \"YOUR_MESSAGING_SENDER_ID\",\n      appId: \"YOUR_APP_ID\"\n    };\n\n    let app = null, auth = null, db = null;\n    const isFirebaseConfigured = firebaseConfig.apiKey !== \"YOUR_API_KEY\" && Boolean(firebaseConfig.projectId);\n\n    if (isFirebaseConfigured) {\n      try {\n        app = initializeApp(firebaseConfig);\n        auth = getAuth(app);\n        db = getFirestore(app);\n      } catch (err) {\n        console.warn(\"Firebase 초기화 에러, Mock 모드로 진행:\", err);\n      }\n    }\n\n    function calculateScore(age, tenure, totalExp) {\n      let ageScore = 10;\n      if (age >= 55) ageScore = 30;\n      else if (age >= 50) ageScore = 25;\n      else if (age >= 45) ageScore = 20;\n      else if (age >= 40) ageScore = 15;\n\n      let tenureScore = 0;\n      if (tenure >= 10) tenureScore = 30;\n      else if (tenure >= 5) tenureScore = 20;\n      else if (tenure >= 1) tenureScore = 10;\n\n      let expScore = 10;\n      if (totalExp >= 20) expScore = 40;\n      else if (totalExp >= 10) expScore = 30;\n      else if (totalExp >= 5) expScore = 20;\n\n      return {\n        ageScore,\n        tenureScore,\n        expScore,\n        totalScore: ageScore + tenureScore + expScore\n      };\n    }\n    window.calculateScore = calculateScore;\n\n    function formatYearMonthDisplay(val) {\n      if (val === undefined || val === null || val === '') return '';\n      const str = String(val).trim();\n      const num = parseFloat(str);\n      if (isNaN(num) || num < 0) return '';\n      const parts = str.split('.');\n      const years = parseInt(parts[0] || '0', 10);\n      if (parts.length < 2 || !parts[1]) return `${years}년`;\n      const monthStr = parts[1].padEnd(2, '0').slice(0, 2);\n      const months = parseInt(monthStr, 10);\n      if (months === 0) return `${years}년`;\n      return `${years}년 ${months}개월`;\n    }\n    window.formatYearMonthDisplay = formatYearMonthDisplay;\n\n    let mockRotationRecords = [\n      {\n        id: 'rec-001',\n        name: '박지원',\n        affiliation: '2학년 1반',\n        age: 56,\n        tenure: 12,\n        totalExp: 22,\n        currentDuties: '플랫폼 시스템 아키텍처 및 2학년 전산 실무 강의',\n        scoreBreakdown: { ageScore: 30, tenureScore: 30, expScore: 40, totalScore: 100, ageTier: '55세 이상', tenureTier: '10년 이상', expTier: '20년 이상' },\n        savedAt: '2026-10-27 15:30'\n      },\n      {\n        id: 'rec-002',\n        name: '홍길동',\n        affiliation: '2학년 3반',\n        age: 52,\n        tenure: 8,\n        totalExp: 16,\n        currentDuties: '영업기획팀 파이프라인 관리 및 2학년 취업 진로 상담 전담',\n        scoreBreakdown: { ageScore: 25, tenureScore: 20, expScore: 30, totalScore: 75, ageTier: '50~54세', tenureTier: '5~9년', expTier: '10~19년' },\n        savedAt: '2026-10-28 14:20'\n      },\n      {\n        id: 'rec-003',\n        name: '최영호',\n        affiliation: '1학년 4반',\n        age: 42,\n        tenure: 3,\n        totalExp: 8,\n        currentDuties: '디지털 마케팅 캠페인 운영 및 SNS 채널 관리',\n        scoreBreakdown: { ageScore: 15, tenureScore: 10, expScore: 20, totalScore: 45, ageTier: '40~44세', tenureTier: '1~4년', expTier: '5~9년' },\n        savedAt: '2026-10-28 11:10'\n      }\n    ];\n\n    let currentUser = null;\n\n    // 경고 모달 표시 함수\n    function showWarningModal(msg = '로그인을 해주세요.') {\n      document.getElementById('warning-modal-text').textContent = msg;\n      document.getElementById('warning-modal').classList.remove('hidden');\n    }\n    window.showWarningModal = showWarningModal;\n\n    function closeWarningModal() {\n      document.getElementById('warning-modal').classList.add('hidden');\n      ViewController.navigate('login');\n    }\n    window.closeWarningModal = closeWarningModal;\n\n    const ViewController = {\n      currentView: 'login',\n\n      init() {\n        this.updateNavUI();\n      },\n\n      navigate(viewName) {\n        // [네비게이션 가드] 미로그인 상태에서 다른 페이지 접근 시 경고창 표시\n        if (viewName !== 'login' && !currentUser) {\n          showWarningModal('로그인을 해주세요.');\n          return;\n        }\n\n        if (viewName === 'admin' && currentUser && currentUser.role !== 'admin') {\n          showWarningModal('관리자 권한이 필요합니다.');\n          return;\n        }\n\n        document.querySelectorAll('.view-section').forEach(el => el.classList.remove('active'));\n        const target = document.getElementById(`view-${viewName}`);\n        if (target) {\n          target.classList.add('active');\n          this.currentView = viewName;\n          this.updateNavUI();\n\n          if (viewName === 'career') {\n            CareerScoreApp.handleLiveCalc();\n          } else if (viewName === 'admin') {\n            CareerScoreApp.renderAdminTable();\n          }\n        }\n      },\n\n      updateNavUI() {\n        ['login', 'career', 'admin'].forEach(v => {\n          const btn = document.getElementById(`nav-btn-${v}`);\n          if (!btn) return;\n          if (v === this.currentView) {\n            btn.className = \"px-3.5 py-1.5 rounded-lg text-sm font-bold text-brand-600 bg-brand-50 border border-brand-200 transition-colors\";\n          } else {\n            btn.className = \"px-3.5 py-1.5 rounded-lg text-sm font-medium text-slate-600 hover:text-brand-600 hover:bg-slate-100 transition-colors\";\n          }\n        });\n      }\n    };\n\n    let currentAuthMode = 'login';\n\n    const AuthService = {\n      updateLoginButtonState() {\n        const nameVal = document.getElementById('auth-name').value.trim();\n        const affVal = document.getElementById('auth-affiliation').value.trim();\n        const pwVal = document.getElementById('auth-password').value.trim();\n        const pwConfirmVal = (document.getElementById('auth-password-confirm')?.value || '').trim();\n        const btn = document.getElementById('btn-login-submit');\n        const textSpan = document.getElementById('login-text');\n        const hint = document.getElementById('login-guide-hint');\n\n        const isAdminTarget = nameVal.toLowerCase() === 'admin';\n        const isFilled = nameVal.length > 0 && (isAdminTarget || affVal.length > 0) && pwVal.length > 0;\n\n        if (btn && textSpan) {\n          if (isFilled) {\n            btn.className = \"w-full py-3.5 bg-gradient-to-r from-brand-600 to-indigo-600 hover:from-brand-700 hover:to-indigo-700 text-white font-black shadow-lg shadow-brand-500/30 scale-[1.01] rounded-xl transition flex items-center justify-center space-x-2 text-sm cursor-pointer\";\n            textSpan.className = \"font-black text-white text-base tracking-wider\";\n            textSpan.textContent = \"로그인\";\n            if (hint) hint.classList.add('hidden');\n          } else {\n            btn.className = \"w-full py-3.5 bg-slate-200 hover:bg-slate-300 text-slate-700 font-bold border border-slate-300 rounded-xl transition flex items-center justify-center space-x-2 text-sm cursor-pointer\";\n            textSpan.className = \"font-bold text-slate-700 text-sm\";\n            textSpan.textContent = \"로그인\";\n            if (hint) hint.classList.remove('hidden');\n          }\n        }\n\n        // 회원가입 버튼 상태 동적 업데이트\n        const btnSignup = document.getElementById('btn-signup-submit');\n        const textSignup = document.getElementById('signup-text');\n        const arrowSignup = document.getElementById('signup-arrow');\n        const isSignupFilled = isFilled && pwConfirmVal.length > 0 && pwVal === pwConfirmVal;\n\n        if (btnSignup && textSignup) {\n          textSignup.textContent = \"가입하기\";\n          if (isSignupFilled) {\n            btnSignup.className = \"w-full py-3 bg-indigo-600 hover:bg-indigo-700 active:bg-indigo-800 text-white font-black rounded-xl transition shadow-lg shadow-indigo-500/30 scale-[1.01] flex items-center justify-center space-x-1.5 text-sm cursor-pointer select-none\";\n            textSignup.className = \"text-white font-black text-sm tracking-wide\";\n            if (arrowSignup) arrowSignup.className = \"w-4 h-4 text-white ml-0.5\";\n          } else {\n            btnSignup.className = \"w-full py-3 bg-slate-200 hover:bg-slate-300 text-slate-700 font-bold border border-slate-300 rounded-xl transition flex items-center justify-center space-x-1.5 text-sm cursor-pointer select-none\";\n            textSignup.className = \"text-slate-700 font-bold text-sm\";\n            if (arrowSignup) arrowSignup.className = \"w-4 h-4 text-slate-600 ml-0.5\";\n          }\n        }\n      },\n\n      switchAuthMode(mode) {\n        currentAuthMode = mode;\n        const tabLogin = document.getElementById('tab-login');\n        const tabSignup = document.getElementById('tab-signup');\n        const title = document.getElementById('auth-title');\n        const subtitle = document.getElementById('auth-subtitle');\n        const pwConfirm = document.getElementById('field-password-confirm');\n        const pwConfirmInput = document.getElementById('auth-password-confirm');\n        const btnLogin = document.getElementById('btn-login-single');\n        const btnSignup = document.getElementById('btn-signup-group');\n        const adminChkLabel = document.getElementById('admin-chk-label');\n\n        if (mode === 'signup') {\n          tabSignup.className = \"py-2 text-xs font-bold rounded-lg transition-all bg-white text-brand-600 shadow-xs\";\n          tabLogin.className = \"py-2 text-xs font-bold rounded-lg transition-all text-slate-500 hover:text-slate-800\";\n          title.textContent = \"순환보직 신규 회원가입\";\n          subtitle.textContent = \"새로운 계정 정보를 입력하여 회원가입을 완료하세요.\";\n          pwConfirm.classList.remove('hidden');\n          pwConfirmInput.setAttribute('required', 'true');\n          adminChkLabel.textContent = \"관리자(교사 / 인사담당자)로 가입\";\n          btnLogin.classList.add('hidden');\n          btnSignup.classList.remove('hidden');\n        } else {\n          tabLogin.className = \"py-2 text-xs font-bold rounded-lg transition-all bg-white text-brand-600 shadow-xs\";\n          tabSignup.className = \"py-2 text-xs font-bold rounded-lg transition-all text-slate-500 hover:text-slate-800\";\n          title.textContent = \"순환보직 평정 시스템 로그인\";\n          subtitle.textContent = \"이름과 학년/반(소속)으로 로그인하세요.\";\n          pwConfirm.classList.add('hidden');\n          pwConfirmInput.removeAttribute('required');\n          pwConfirmInput.value = '';\n          adminChkLabel.textContent = \"관리자(교사 / 인사담당자)로 로그인\";\n          btnLogin.classList.remove('hidden');\n          btnSignup.classList.add('hidden');\n          this.updateLoginButtonState();\n        }\n      },\n\n      async handleSubmit(event) {\n        event.preventDefault();\n        const name = document.getElementById('auth-name').value.trim();\n        const affiliation = document.getElementById('auth-affiliation').value.trim();\n        const password = document.getElementById('auth-password').value;\n        const isAdminTarget = (name.toLowerCase() === 'admin');\n\n        // [미입력 시 경고창 노출: admin은 소속 생략 가능]\n        if (!name || (!isAdminTarget && !affiliation) || !password) {\n          showWarningModal('로그인을 해주세요.');\n          return;\n        }\n\n        if (currentAuthMode === 'signup') {\n          const pwConfirm = document.getElementById('auth-password-confirm').value;\n          if (password !== pwConfirm) {\n            showWarningModal(\"비밀번호와 비밀번호 확인이 일치하지 않습니다.\");\n            return;\n          }\n        }\n\n        // [요구사항 핵심 2] 관리자 접속 조건: 아이디는 admin, 비밀번호는 112233 (또는 변경된 비밀번호)\n        const isTargetingAdmin = (name.toLowerCase() === 'admin') || isAdminCheckbox;\n        if (isTargetingAdmin) {\n          if (name.toLowerCase() !== 'admin') {\n            showWarningModal(\"관리자 로그인은 아이디(이름)가 'admin'이어야 합니다.\");\n            return;\n          }\n          const activeAdminPw = localStorage.getItem('admin_password') || '112233';\n          if (password !== activeAdminPw) {\n            showWarningModal(\"관리자 비밀번호가 일치하지 않습니다.\");\n            return;\n          }\n        }\n\n        const isAdmin = isTargetingAdmin;\n        const role = isAdmin ? 'admin' : 'employee';\n\n        currentUser = { name, affiliation: affiliation || (isAdmin ? '교무부 (인사담당)' : '소속 미정'), role };\n\n        const badge = document.getElementById('user-badge');\n        const nameDisplay = document.getElementById('user-name-display');\n        badge.classList.remove('hidden');\n        badge.classList.add('flex');\n        nameDisplay.textContent = `${name} (${currentUser.affiliation}) [${isAdmin ? '관리자' : '직원'}]`;\n\n        showToast(`${name}님 환영합니다!`, \"success\");\n        document.getElementById('career-name').value = name;\n\n        if (isAdmin) {\n          ViewController.navigate('admin');\n        } else {\n          ViewController.navigate('career');\n        }\n      },\n\n      handleSignOut() {\n        if (isFirebaseConfigured && auth) signOut(auth);\n        currentUser = null;\n        document.getElementById('user-badge').classList.add('hidden');\n        document.getElementById('user-badge').classList.remove('flex');\n        showToast(\"로그아웃되었습니다.\", \"info\");\n        ViewController.navigate('login');\n      }\n    };\n\n    const CareerScoreApp = {\n      handleLiveCalc() {\n        const ageVal = document.getElementById('career-age').value;\n        const tenureVal = document.getElementById('career-tenure').value;\n        const totalExpVal = document.getElementById('career-total-exp').value;\n\n        const age = parseFloat(ageVal) || 0;\n        const tenure = parseFloat(tenureVal) || 0;\n        const totalExp = parseFloat(totalExpVal) || 0;\n\n        const result = calculateScore(age, tenure, totalExp);\n\n        document.getElementById('live-age-score').textContent = `${result.ageScore}점`;\n        document.getElementById('live-age-tier').textContent = `${result.ageTier} 구간`;\n\n        document.getElementById('live-tenure-score').textContent = `${result.tenureScore}점`;\n        document.getElementById('live-tenure-tier').textContent = `${result.tenureTier} 구간`;\n\n        document.getElementById('live-exp-score').textContent = `${result.expScore}점`;\n        document.getElementById('live-exp-tier').textContent = `${result.expTier} 구간`;\n\n        const tenureConv = document.getElementById('career-tenure-convert');\n        const expConv = document.getElementById('career-exp-convert');\n        if (tenureConv) tenureConv.textContent = formatYearMonthDisplay(tenureVal);\n        if (expConv) expConv.textContent = formatYearMonthDisplay(totalExpVal);\n\n        return result;\n      },\n\n      async handleSaveRecord(event) {\n        event.preventDefault();\n\n        const name = document.getElementById('career-name').value.trim() || (currentUser ? currentUser.name : '홍길동');\n        const affiliation = currentUser ? currentUser.affiliation : '2학년 3반';\n        const age = parseFloat(document.getElementById('career-age').value) || 0;\n        const tenure = parseFloat(document.getElementById('career-tenure').value) || 0;\n        const totalExp = parseFloat(document.getElementById('career-total-exp').value) || 0;\n        const currentDuties = document.getElementById('career-duties').value.trim();\n\n        const scoreResult = calculateScore(age, tenure, totalExp);\n\n        const recordDoc = {\n          name,\n          affiliation,\n          age,\n          tenure,\n          totalExp,\n          currentDuties,\n          scoreBreakdown: {\n            ageScore: scoreResult.ageScore,\n            tenureScore: scoreResult.tenureScore,\n            expScore: scoreResult.expScore,\n            totalScore: scoreResult.totalScore,\n            ageTier: scoreResult.ageTier,\n            tenureTier: scoreResult.tenureTier,\n            expTier: scoreResult.expTier\n          },\n          savedAt: new Date().toISOString().substring(0, 16).replace('T', ' ')\n        };\n\n        if (isFirebaseConfigured && db) {\n          try {\n            const docRef = await addDoc(collection(db, \"rotation_records\"), {\n              ...recordDoc,\n              createdAt: serverTimestamp()\n            });\n            recordDoc.id = docRef.id;\n            showToast(\"Firestore rotation_records에 저장되었습니다!\", \"success\");\n          } catch (e) {\n            recordDoc.id = 'rec-' + Date.now();\n            showToast(\"로컬에 저장되었습니다.\", \"warning\");\n          }\n        } else {\n          recordDoc.id = 'rec-' + Date.now();\n          showToast(\"경력 정보 및 배점이 저장되었습니다!\", \"success\");\n        }\n\n        const existingIdx = mockRotationRecords.findIndex(r => r.name === name);\n        if (existingIdx >= 0) {\n          mockRotationRecords[existingIdx] = recordDoc;\n        } else {\n          mockRotationRecords.unshift(recordDoc);\n        }\n\n        this.displayResultCard(recordDoc);\n      },\n\n      displayResultCard(record) {\n        const container = document.getElementById('result-score-container');\n        document.getElementById('result-user-name').textContent = record.name;\n        document.getElementById('result-total-score').textContent = record.scoreBreakdown.totalScore;\n        document.getElementById('result-chip-age').textContent = `${record.scoreBreakdown.ageScore}점`;\n        document.getElementById('result-chip-tenure').textContent = `${record.scoreBreakdown.tenureScore}점`;\n        document.getElementById('result-chip-exp').textContent = `${record.scoreBreakdown.expScore}점`;\n        document.getElementById('result-timestamp').textContent = `평정 일시: ${record.savedAt}`;\n\n        const total = record.scoreBreakdown.totalScore;\n        const rankTierEl = document.getElementById('result-rank-tier');\n        if (total >= 80) {\n          rankTierEl.textContent = \"★ 순환배치 1순위 (80점 이상 특우선군)\";\n        } else if (total >= 60) {\n          rankTierEl.textContent = \"● 순환배치 권장 대상 (60점 ~ 79점 일반순환군)\";\n        } else {\n          rankTierEl.textContent = \"○ 기본 검토 대상 (60점 미만 유예/잔류 검토군)\";\n        }\n\n        container.scrollIntoView({ behavior: 'smooth', block: 'center' });\n      },\n\n      selectedRecordId: null,\n      recordToDeleteId: null,\n\n      handleSelectRecord(id) {\n        this.selectedRecordId = id;\n        const btnDelete = document.getElementById('btn-admin-delete');\n        if (btnDelete) {\n          btnDelete.removeAttribute('disabled');\n          btnDelete.className = \"px-3.5 py-2 rounded-xl text-xs font-bold transition flex items-center space-x-1.5 bg-rose-600 hover:bg-rose-700 text-white cursor-pointer shadow-md shadow-rose-500/25\";\n        }\n      },\n\n      handleDeleteSelected() {\n        if (!this.selectedRecordId) return;\n        this.openDeleteModal(this.selectedRecordId);\n      },\n\n      openDeleteModal(id) {\n        this.recordToDeleteId = id;\n        const rec = mockRotationRecords.find(r => r.id === id);\n        if (!rec) return;\n\n        document.getElementById('delete-target-name').textContent = rec.name;\n        document.getElementById('delete-target-aff').textContent = rec.affiliation;\n        document.getElementById('delete-target-score').textContent = `${rec.scoreBreakdown.totalScore}점`;\n        document.getElementById('admin-delete-modal').classList.remove('hidden');\n      },\n\n      closeDeleteModal() {\n        this.recordToDeleteId = null;\n        document.getElementById('admin-delete-modal').classList.add('hidden');\n      },\n\n      executeDelete() {\n        if (!this.recordToDeleteId) return;\n        const id = this.recordToDeleteId;\n        const recIndex = mockRotationRecords.findIndex(r => r.id === id);\n        if (recIndex === -1) {\n          this.closeDeleteModal();\n          return;\n        }\n\n        const target = mockRotationRecords[recIndex];\n        // 1. rotation_records에서 삭제\n        mockRotationRecords.splice(recIndex, 1);\n\n        // 2. 로그인 세션 또는 사용자 목록에서 삭제\n        if (currentUser && currentUser.name === target.name) {\n          currentUser = null;\n          document.getElementById('user-badge').classList.add('hidden');\n          document.getElementById('user-badge').classList.remove('flex');\n          showToast(`현재 접속 중인 [${target.name}] 교직원의 평정 기록 및 로그인 계정이 삭제되어 로그아웃되었습니다.`, 'warning');\n          ViewController.navigate('login');\n        } else {\n          showToast(`[${target.name} (${target.affiliation})] 교직원의 평정 데이터 및 로그인 계정 정보가 모두 삭제되었습니다.`, 'success');\n        }\n\n        if (this.selectedRecordId === id) {\n          this.selectedRecordId = null;\n          const btnDelete = document.getElementById('btn-admin-delete');\n          if (btnDelete) {\n            btnDelete.setAttribute('disabled', 'true');\n            btnDelete.className = \"px-3.5 py-2 rounded-xl text-xs font-bold transition flex items-center space-x-1.5 bg-slate-100 text-slate-400 border border-slate-200 cursor-not-allowed opacity-60\";\n          }\n        }\n\n        this.closeDeleteModal();\n        this.renderAdminTable();\n      },\n\n      // [요구사항 핵심 3] 관리자 비밀번호 변경 팝업 모달 제어\n      openPasswordModal() {\n        document.getElementById('pw-current').value = '';\n        document.getElementById('pw-new').value = '';\n        document.getElementById('pw-new-confirm').value = '';\n        document.getElementById('pw-error-box').classList.add('hidden');\n        document.getElementById('pw-success-box').classList.add('hidden');\n        document.getElementById('admin-pw-modal').classList.remove('hidden');\n      },\n\n      closePasswordModal() {\n        document.getElementById('admin-pw-modal').classList.add('hidden');\n      },\n\n      submitChangePassword(e) {\n        e.preventDefault();\n        const curPw = document.getElementById('pw-current').value;\n        const newPw = document.getElementById('pw-new').value;\n        const confirmPw = document.getElementById('pw-new-confirm').value;\n        const errorBox = document.getElementById('pw-error-box');\n        const errorMsg = document.getElementById('pw-error-msg');\n        const successBox = document.getElementById('pw-success-box');\n        const successMsg = document.getElementById('pw-success-msg');\n\n        errorBox.classList.add('hidden');\n        successBox.classList.add('hidden');\n\n        const activeAdminPw = localStorage.getItem('admin_password') || '112233';\n\n        if (!curPw) {\n          errorMsg.textContent = '이전 비밀번호를 입력해 주세요.';\n          errorBox.classList.remove('hidden');\n          return;\n        }\n        if (curPw !== activeAdminPw) {\n          errorMsg.textContent = '이전 비밀번호가 일치하지 않습니다.';\n          errorBox.classList.remove('hidden');\n          return;\n        }\n        if (!newPw) {\n          errorMsg.textContent = '새로운 비밀번호를 입력해 주세요.';\n          errorBox.classList.remove('hidden');\n          return;\n        }\n        if (newPw.length < 4) {\n          errorMsg.textContent = '새로운 비밀번호는 4자 이상 입력해 주세요.';\n          errorBox.classList.remove('hidden');\n          return;\n        }\n        if (newPw !== confirmPw) {\n          errorMsg.textContent = '새로운 비밀번호와 확인 입력이 일치하지 않습니다. 2번 반복하여 정확히 입력해 주세요.';\n          errorBox.classList.remove('hidden');\n          return;\n        }\n\n        localStorage.setItem('admin_password', newPw);\n        successMsg.textContent = '관리자 비밀번호가 성공적으로 변경되었습니다!';\n        successBox.classList.remove('hidden');\n        showToast('관리자 비밀번호가 성공적으로 변경되었습니다.', 'success');\n\n        setTimeout(() => {\n          CareerScoreApp.closePasswordModal();\n        }, 1200);\n      },\n\n      renderAdminTable() {\n        const tbody = document.getElementById('admin-records-table-body');\n        if (!tbody) return;\n\n        const sorted = [...mockRotationRecords].sort((a, b) => b.scoreBreakdown.totalScore - a.scoreBreakdown.totalScore);\n\n        document.getElementById('admin-stat-records').textContent = `${sorted.length}건`;\n        if (sorted.length > 0) {\n          document.getElementById('admin-stat-top-score').textContent = `${sorted[0].scoreBreakdown.totalScore}점`;\n          const avg = (sorted.reduce((acc, cur) => acc + cur.scoreBreakdown.totalScore, 0) / sorted.length).toFixed(1);\n          document.getElementById('admin-stat-avg-score').textContent = `${avg}점`;\n          const priorityCount = sorted.filter(r => r.scoreBreakdown.totalScore >= 70).length;\n          document.getElementById('admin-stat-priority').textContent = `${priorityCount}명`;\n        } else {\n          document.getElementById('admin-stat-top-score').textContent = \"0점\";\n          document.getElementById('admin-stat-avg-score').textContent = \"0점\";\n          document.getElementById('admin-stat-priority').textContent = \"0명\";\n        }\n\n        if (sorted.length === 0) {\n          tbody.innerHTML = `\n            <tr>\n              <td colspan=\"8\" class=\"px-5 py-8 text-center text-slate-400\">\n                등록된 평정 기록이 없습니다.\n              </td>\n            </tr>\n          `;\n          return;\n        }\n\n        tbody.innerHTML = sorted.map((rec, index) => {\n          const total = rec.scoreBreakdown.totalScore;\n          let scoreBadgeColor = \"bg-slate-100 text-slate-700\";\n          if (total >= 80) scoreBadgeColor = \"bg-purple-100 text-purple-700 font-extrabold\";\n          else if (total >= 65) scoreBadgeColor = \"bg-emerald-100 text-emerald-700 font-bold\";\n          else scoreBadgeColor = \"bg-amber-100 text-amber-700\";\n\n          const isChecked = this.selectedRecordId === rec.id;\n\n          return `\n            <tr class=\"hover:bg-slate-50/80 transition-colors ${isChecked ? 'bg-rose-50/60' : ''}\">\n              <td class=\"px-3.5 py-3.5 text-center\">\n                <input type=\"radio\" name=\"adminRecordRadio\" value=\"${rec.id}\" ${isChecked ? 'checked' : ''} onchange=\"CareerScoreApp.handleSelectRecord('${rec.id}')\" class=\"w-4 h-4 text-rose-600 cursor-pointer accent-rose-600\" />\n              </td>\n              <td class=\"px-5 py-3.5 font-bold text-slate-500\">${index + 1}위</td>\n              <td class=\"px-5 py-3.5\">\n                <div class=\"font-bold text-slate-900\">${rec.name}</div>\n                <div class=\"text-xs text-slate-400\">${rec.affiliation}</div>\n              </td>\n              <td class=\"px-5 py-3.5 text-xs text-slate-600\">\n                <div>만 ${rec.age}세 · 재직 ${formatYearMonthDisplay(rec.tenure)}</div>\n                <div class=\"text-[11px] text-slate-400\">총경력 ${formatYearMonthDisplay(rec.totalExp)}</div>\n              </td>\n              <td class=\"px-5 py-3.5 text-xs\">\n                <span class=\"text-brand-700 font-medium\">나이 ${rec.scoreBreakdown.ageScore}</span> + \n                <span class=\"text-indigo-700 font-medium\">재직 ${rec.scoreBreakdown.tenureScore}</span> + \n                <span class=\"text-purple-700 font-medium\">경력 ${rec.scoreBreakdown.expScore}</span>\n              </td>\n              <td class=\"px-5 py-3.5 text-center\">\n                <span class=\"px-3 py-1 rounded-full text-xs ${scoreBadgeColor}\">\n                  ${total}점\n                </span>\n              </td>\n              <td class=\"px-5 py-3.5 text-xs text-slate-500 max-w-xs truncate\" title=\"${rec.currentDuties}\">\n                ${rec.currentDuties}\n              </td>\n              <td class=\"px-5 py-3.5 text-right\">\n                <button onclick=\"CareerScoreApp.openDeleteModal('${rec.id}')\" class=\"px-2.5 py-1 border border-rose-200 hover:border-rose-400 hover:bg-rose-50 bg-white rounded-lg text-rose-600 font-bold text-xs inline-flex items-center cursor-pointer transition\">\n                  <svg class=\"w-3.5 h-3.5 mr-1 text-rose-600\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16\" /></svg>\n                  <span>삭제</span>\n                </button>\n              </td>\n            </tr>\n          `;\n        }).join('');\n      }\n    };\n\n    function showToast(message, type = 'info') {\n      const container = document.getElementById('toast-container');\n      const toast = document.createElement('div');\n      \n      let bg = \"bg-slate-900 text-white\";\n      if (type === 'success') bg = \"bg-emerald-600 text-white\";\n      if (type === 'warning') bg = \"bg-amber-600 text-white\";\n      if (type === 'error') bg = \"bg-rose-600 text-white\";\n\n      toast.className = `${bg} px-4 py-3 rounded-xl shadow-lg text-sm font-medium transition-all transform duration-300 translate-y-2 opacity-0 pointer-events-auto flex items-center space-x-2`;\n      toast.innerHTML = `\n        <svg class=\"w-4 h-4 shrink-0\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n        <span>${message}</span>\n      `;\n      container.appendChild(toast);\n\n      requestAnimationFrame(() => {\n        toast.classList.remove('translate-y-2', 'opacity-0');\n      });\n\n      setTimeout(() => {\n        toast.classList.add('opacity-0', '-translate-y-2');\n        setTimeout(() => toast.remove(), 300);\n      }, 3500);\n    }\n\n    window.ViewController = ViewController;\n    window.AuthService = AuthService;\n    window.CareerScoreApp = CareerScoreApp;\n    window.showToast = showToast;\n\n    document.addEventListener('DOMContentLoaded', () => {\n      ViewController.init();\n      AuthService.updateLoginButtonState();\n    });\n  </script>\n</body>\n</html>\n";
